create table if not exists public.roadmap_tasks (
  id bigint generated by default as identity primary key,
  source_key text unique,
  parent_id bigint references public.roadmap_tasks(id) on delete cascade,
  phase text not null,
  title text not null,
  description text,
  status text not null default 'Bereit',
  priority text not null default 'Bald',
  owner text default 'Gemeinsam',
  due_date date,
  dependency text,
  notes text,
  sort_order integer not null default 100,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

alter table public.roadmap_tasks enable row level security;

drop policy if exists "Authenticated users can read roadmap tasks" on public.roadmap_tasks;
create policy "Authenticated users can read roadmap tasks"
on public.roadmap_tasks for select to authenticated using (true);

drop policy if exists "Authenticated users can create roadmap tasks" on public.roadmap_tasks;
create policy "Authenticated users can create roadmap tasks"
on public.roadmap_tasks for insert to authenticated with check (true);

drop policy if exists "Authenticated users can update roadmap tasks" on public.roadmap_tasks;
create policy "Authenticated users can update roadmap tasks"
on public.roadmap_tasks for update to authenticated using (true) with check (true);

drop policy if exists "Authenticated users can delete roadmap tasks" on public.roadmap_tasks;
create policy "Authenticated users can delete roadmap tasks"
on public.roadmap_tasks for delete to authenticated using (true);

grant select, insert, update, delete on table public.roadmap_tasks to authenticated;
grant usage, select on all sequences in schema public to authenticated;

